{"command": "echo "import numpy as np
from io import BytesIO

c = BytesIO()
try:
    np.savetxt(c, np.array(1))  # 0D array
except ValueError as e:
    print(f'0D array error: {e}')

try:
    np.savetxt(c, np.array([[[1], [2]]]))  # 3D array
except ValueError as e:
    print(f'3D array error: {e}')" > /testbed/test_savetxt.py"}

